-- Ledger-shaped schema: SHOW CREATE TABLE of a database produced by the migrations alone, normalized.
-- Used by lumen/scripts/schema_repair.py to restore missing tables, columns and keys at bootstrap. Do not edit:
-- tests/integration/test_schema_index_drift.py compares it with the ledger result. Regenerate with
-- LUMEN_UPDATE_SCHEMA_SNAPSHOT=1 uv run lumen-test integration -k schema_snapshot

CREATE TABLE `chat_agent_reservations` (
  `id` char(36) NOT NULL,
  `project_id` varchar(64) NOT NULL,
  `root_run_id` char(36) NOT NULL,
  `run_id` char(36) NOT NULL,
  `kind` varchar(20) NOT NULL,
  `amount` decimal(18,8) NOT NULL,
  `settled_amount` decimal(18,8) DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'reserved',
  `settled_at` datetime(6) DEFAULT NULL,
  `released_at` datetime(6) DEFAULT NULL,
  `created_at` datetime(6) NOT NULL DEFAULT current_timestamp(6),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_agent_reservation_run_kind` (`run_id`,`kind`),
  KEY `idx_agent_reservation_root` (`root_run_id`,`status`),
  CONSTRAINT `fk_agent_reservation_root` FOREIGN KEY (`root_run_id`) REFERENCES `chat_runs` (`id`),
  CONSTRAINT `fk_agent_reservation_run` FOREIGN KEY (`run_id`) REFERENCES `chat_runs` (`id`)
) ENGINE=InnoDB;

CREATE TABLE `chat_agents` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `owner_user_id` varchar(64) NOT NULL,
  `project_id` varchar(64) DEFAULT NULL,
  `name` varchar(100) NOT NULL,
  `description` varchar(500) DEFAULT NULL,
  `avatar` varchar(500) DEFAULT NULL,
  `instructions` mediumtext DEFAULT NULL,
  `model_name` varchar(190) DEFAULT NULL,
  `params` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`params`)),
  `mcp_ids` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`mcp_ids`)),
  `tool_ids` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`tool_ids`)),
  `skill_ids` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`skill_ids`)),
  `visibility` varchar(10) NOT NULL,
  `role` varchar(20) NOT NULL,
  `execution_policy` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`execution_policy`)),
  `delegable_agent_ids` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`delegable_agent_ids`)),
  `cloned_from_id` bigint DEFAULT NULL,
  `clone_count` int NOT NULL,
  `is_active` tinyint NOT NULL,
  `content_hash` char(64) DEFAULT NULL,
  `source_package_id` char(36) DEFAULT NULL,
  `source_package_version` varchar(64) DEFAULT NULL,
  `managed_by_package` tinyint NOT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `plugin_tool_ids` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`plugin_tool_ids`)),
  `plugin_skill_ids` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`plugin_skill_ids`)),
  PRIMARY KEY (`id`),
  KEY `idx_chat_agents_owner` (`owner_user_id`),
  KEY `idx_chat_agents_project` (`project_id`),
  KEY `idx_chat_agents_project_active` (`project_id`,`is_active`),
  KEY `idx_chat_agents_visibility` (`visibility`)
) ENGINE=InnoDB;

CREATE TABLE `chat_api_keys` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `owner_user_id` varchar(64) NOT NULL,
  `owner_project_id` varchar(64) NOT NULL,
  `name` varchar(100) NOT NULL,
  `key_prefix` varchar(24) NOT NULL,
  `key_hash` char(64) NOT NULL,
  `is_active` tinyint NOT NULL,
  `last_used_at` datetime DEFAULT NULL,
  `revoked_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `scopes` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`scopes`)),
  `owner_monthly_credit_limit` decimal(18,8) DEFAULT NULL,
  `admin_monthly_credit_limit` decimal(18,8) DEFAULT NULL,
  `owner_weekly_credit_limit` decimal(18,8) DEFAULT NULL,
  `expires_at` datetime(6) DEFAULT NULL,
  `credential_kind` varchar(32) NOT NULL DEFAULT 'api_key',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_chat_api_keys_hash` (`key_hash`),
  KEY `idx_chat_api_keys_owner` (`owner_user_id`,`owner_project_id`),
  CONSTRAINT `chk_chat_api_keys_owner_monthly_credit_limit` CHECK (`owner_monthly_credit_limit` is null or `owner_monthly_credit_limit` > 0),
  CONSTRAINT `chk_chat_api_keys_admin_monthly_credit_limit` CHECK (`admin_monthly_credit_limit` is null or `admin_monthly_credit_limit` > 0),
  CONSTRAINT `chk_chat_api_keys_owner_weekly_credit_limit` CHECK (`owner_weekly_credit_limit` is null or `owner_weekly_credit_limit` > 0),
  CONSTRAINT `chk_chat_api_keys_credential_kind` CHECK (`credential_kind` in ('api_key','claude_gateway'))
) ENGINE=InnoDB;

CREATE TABLE `chat_assets` (
  `id` char(36) NOT NULL,
  `project_id` varchar(64) NOT NULL,
  `user_id` varchar(64) NOT NULL,
  `object_key` varchar(255) NOT NULL,
  `bucket_name` varchar(63) DEFAULT NULL,
  `original_name` varchar(255) NOT NULL,
  `mime_type` varchar(127) NOT NULL,
  `size_bytes` bigint NOT NULL,
  `sha256` char(64) NOT NULL,
  `status` varchar(20) NOT NULL,
  `media_metadata` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`media_metadata`)),
  `expires_at` datetime DEFAULT NULL,
  `deleting_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `object_key` (`object_key`),
  KEY `idx_chat_assets_expiry` (`expires_at`),
  KEY `idx_chat_assets_owner_status` (`project_id`,`user_id`,`status`)
) ENGINE=InnoDB;

CREATE TABLE `chat_batch_files` (
  `id` char(36) NOT NULL,
  `project_id` varchar(64) NOT NULL,
  `user_id` varchar(64) NOT NULL,
  `api_key_id` bigint DEFAULT NULL,
  `purpose` varchar(20) NOT NULL,
  `filename` varchar(255) NOT NULL,
  `mime_type` varchar(127) NOT NULL,
  `size_bytes` bigint NOT NULL DEFAULT 0,
  `sha256` char(64) DEFAULT NULL,
  `bucket_name` varchar(63) NOT NULL,
  `object_key` varchar(255) NOT NULL,
  `state` varchar(20) NOT NULL DEFAULT 'uploading',
  `scan_result` varchar(20) DEFAULT NULL,
  `multipart_upload_id` varchar(1024) DEFAULT NULL,
  `upload_epoch` bigint NOT NULL DEFAULT 0,
  `created_at` datetime(6) NOT NULL DEFAULT current_timestamp(6),
  `expires_at` datetime(6) NOT NULL,
  `deleted_at` datetime(6) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_chat_batch_files_object_key` (`object_key`),
  KEY `idx_chat_batch_files_owner_cursor` (`project_id`,`user_id`,`created_at`,`id`),
  KEY `idx_chat_batch_files_expiry_state` (`expires_at`,`state`),
  CONSTRAINT `ck_chat_batch_files_purpose` CHECK (`purpose` in ('batch','batch_output')),
  CONSTRAINT `ck_chat_batch_files_state` CHECK (`state` in ('uploading','processed','error','deleting','deleted')),
  CONSTRAINT `ck_chat_batch_files_counters` CHECK (`size_bytes` >= 0 and `upload_epoch` >= 0)
) ENGINE=InnoDB;

CREATE TABLE `chat_batch_items` (
  `batch_id` char(36) NOT NULL,
  `ordinal` int NOT NULL,
  `custom_id` varchar(64) NOT NULL,
  `custom_id_hash` char(64) NOT NULL,
  `operation` varchar(30) NOT NULL,
  `request_ciphertext` mediumtext NOT NULL,
  `result_ciphertext` mediumtext DEFAULT NULL,
  `capability_snapshot` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`capability_snapshot`)),
  `pricing_snapshot` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`pricing_snapshot`)),
  `required_scopes` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`required_scopes`)),
  `input_asset_id` char(36) DEFAULT NULL,
  `run_id` char(36) DEFAULT NULL,
  `state` varchar(20) NOT NULL DEFAULT 'pending',
  `error_code` varchar(100) DEFAULT NULL,
  `error_message` varchar(1000) DEFAULT NULL,
  `http_status` int DEFAULT NULL,
  `request_id` varchar(190) DEFAULT NULL,
  `settlement_status` varchar(20) NOT NULL DEFAULT 'pending',
  PRIMARY KEY (`batch_id`,`ordinal`),
  UNIQUE KEY `uq_chat_batch_items_custom_hash` (`batch_id`,`custom_id_hash`),
  UNIQUE KEY `uq_chat_batch_items_run` (`run_id`),
  KEY `idx_chat_batch_items_state_ordinal` (`batch_id`,`state`,`ordinal`),
  KEY `idx_chat_batch_items_input_asset` (`input_asset_id`),
  CONSTRAINT `fk_chat_batch_items_batch` FOREIGN KEY (`batch_id`) REFERENCES `chat_batches` (`id`),
  CONSTRAINT `fk_chat_batch_items_input_asset` FOREIGN KEY (`input_asset_id`) REFERENCES `chat_assets` (`id`),
  CONSTRAINT `fk_chat_batch_items_run` FOREIGN KEY (`run_id`) REFERENCES `chat_runs` (`id`),
  CONSTRAINT `ck_chat_batch_items_ordinal` CHECK (`ordinal` >= 1),
  CONSTRAINT `ck_chat_batch_items_custom_id` CHECK (char_length(`custom_id`) between 1 and 64),
  CONSTRAINT `ck_chat_batch_items_operation` CHECK (`operation` in ('chat.completions','responses','images.generations','images.edits','audio.speech','audio.transcriptions')),
  CONSTRAINT `ck_chat_batch_items_state` CHECK (`state` in ('pending','queued','running','completed','failed','cancelled','expired','unknown')),
  CONSTRAINT `ck_chat_batch_items_http_status` CHECK (`http_status` is null or `http_status` between 100 and 599)
) ENGINE=InnoDB;

CREATE TABLE `chat_batch_project_queues` (
  `project_id` varchar(64) NOT NULL,
  `last_batch_id` char(36) DEFAULT NULL,
  `lease_owner` varchar(190) DEFAULT NULL,
  `lease_fence` bigint NOT NULL DEFAULT 0,
  `lease_expires_at` datetime(6) DEFAULT NULL,
  PRIMARY KEY (`project_id`),
  CONSTRAINT `ck_chat_batch_project_queues_fence` CHECK (`lease_fence` >= 0)
) ENGINE=InnoDB;

CREATE TABLE `chat_batches` (
  `id` char(36) NOT NULL,
  `project_id` varchar(64) NOT NULL,
  `user_id` varchar(64) NOT NULL,
  `api_key_id` bigint DEFAULT NULL,
  `contract` varchar(10) NOT NULL,
  `endpoint` varchar(64) DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'validating',
  `final_target_status` varchar(20) DEFAULT NULL,
  `metadata` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '{}' CHECK (json_valid(`metadata`)),
  `idempotency_key_hash` char(64) DEFAULT NULL,
  `request_fingerprint` char(64) NOT NULL,
  `input_file_id` char(36) DEFAULT NULL,
  `output_file_id` char(36) DEFAULT NULL,
  `error_file_id` char(36) DEFAULT NULL,
  `output_expires_after_seconds` int DEFAULT NULL,
  `request_total` int NOT NULL DEFAULT 0,
  `request_completed` int NOT NULL DEFAULT 0,
  `request_failed` int NOT NULL DEFAULT 0,
  `request_pending` int NOT NULL DEFAULT 0,
  `request_queued` int NOT NULL DEFAULT 0,
  `request_running` int NOT NULL DEFAULT 0,
  `request_cancelled` int NOT NULL DEFAULT 0,
  `request_expired` int NOT NULL DEFAULT 0,
  `request_unknown` int NOT NULL DEFAULT 0,
  `validation_errors` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '[]' CHECK (json_valid(`validation_errors`)),
  `validation_byte_cursor` bigint NOT NULL DEFAULT 0,
  `validation_ordinal_cursor` int NOT NULL DEFAULT 0,
  `lease_owner` varchar(190) DEFAULT NULL,
  `lease_fence` bigint NOT NULL DEFAULT 0,
  `lease_expires_at` datetime(6) DEFAULT NULL,
  `finalization_epoch` bigint NOT NULL DEFAULT 0,
  `created_at` datetime(6) NOT NULL DEFAULT current_timestamp(6),
  `expires_at` datetime(6) NOT NULL DEFAULT (current_timestamp(6) + interval 24 hour),
  `in_progress_at` datetime(6) DEFAULT NULL,
  `finalizing_at` datetime(6) DEFAULT NULL,
  `completed_at` datetime(6) DEFAULT NULL,
  `failed_at` datetime(6) DEFAULT NULL,
  `cancelling_at` datetime(6) DEFAULT NULL,
  `cancelled_at` datetime(6) DEFAULT NULL,
  `expired_at` datetime(6) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_chat_batches_idempotency` (`project_id`,`user_id`,`contract`,`idempotency_key_hash`),
  KEY `idx_chat_batches_owner_cursor` (`project_id`,`user_id`,`created_at`,`id`),
  KEY `idx_chat_batches_status_deadline` (`status`,`expires_at`),
  KEY `idx_chat_batches_input_file` (`input_file_id`),
  KEY `idx_chat_batches_output_file` (`output_file_id`),
  KEY `idx_chat_batches_error_file` (`error_file_id`),
  CONSTRAINT `fk_chat_batches_error_file` FOREIGN KEY (`error_file_id`) REFERENCES `chat_batch_files` (`id`),
  CONSTRAINT `fk_chat_batches_input_file` FOREIGN KEY (`input_file_id`) REFERENCES `chat_batch_files` (`id`),
  CONSTRAINT `fk_chat_batches_output_file` FOREIGN KEY (`output_file_id`) REFERENCES `chat_batch_files` (`id`),
  CONSTRAINT `ck_chat_batches_contract` CHECK (`contract` in ('native','openai')),
  CONSTRAINT `ck_chat_batches_native_idempotency` CHECK (`contract` <> 'native' or `idempotency_key_hash` is not null),
  CONSTRAINT `ck_chat_batches_status` CHECK (`status` in ('validating','in_progress','finalizing','completed','failed','cancelling','cancelled','expired')),
  CONSTRAINT `ck_chat_batches_final_target` CHECK (`final_target_status` is null or `final_target_status` in ('completed','failed','cancelled','expired')),
  CONSTRAINT `ck_chat_batches_request_counters` CHECK (`request_total` >= 0 and `request_completed` >= 0 and `request_failed` >= 0 and `request_pending` >= 0 and `request_queued` >= 0 and `request_running` >= 0 and `request_cancelled` >= 0 and `request_expired` >= 0 and `request_unknown` >= 0),
  CONSTRAINT `ck_chat_batches_progress_counters` CHECK (`validation_byte_cursor` >= 0 and `validation_ordinal_cursor` >= 0 and `lease_fence` >= 0 and `finalization_epoch` >= 0),
  CONSTRAINT `ck_chat_batches_output_expiry` CHECK (`output_expires_after_seconds` is null or `output_expires_after_seconds` between 3600 and 2592000)
) ENGINE=InnoDB;

CREATE TABLE `chat_code_workspace_assets` (
  `workspace_id` char(36) NOT NULL,
  `asset_id` char(36) NOT NULL,
  `purpose` varchar(30) NOT NULL,
  `state_revision` bigint NOT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`workspace_id`,`asset_id`,`purpose`),
  KEY `asset_id` (`asset_id`),
  CONSTRAINT `chat_code_workspace_assets_ibfk_1` FOREIGN KEY (`workspace_id`) REFERENCES `chat_code_workspaces` (`id`),
  CONSTRAINT `chat_code_workspace_assets_ibfk_2` FOREIGN KEY (`asset_id`) REFERENCES `chat_assets` (`id`)
) ENGINE=InnoDB;

CREATE TABLE `chat_code_workspaces` (
  `id` char(36) NOT NULL,
  `owner_user_id` varchar(64) NOT NULL,
  `owner_project_id` varchar(64) NOT NULL,
  `name` varchar(100) NOT NULL,
  `source_kind` varchar(10) NOT NULL,
  `repository_url` varchar(2048) DEFAULT NULL,
  `source_revision` varchar(255) DEFAULT NULL,
  `resolved_base_commit_sha` char(64) DEFAULT NULL,
  `working_branch` varchar(255) NOT NULL,
  `credential_id` bigint DEFAULT NULL,
  `credential_version` bigint DEFAULT NULL,
  `runtime_workspace_id` varchar(255) DEFAULT NULL,
  `lifecycle_status` varchar(20) NOT NULL,
  `state_revision` bigint NOT NULL,
  `runtime_capabilities` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`runtime_capabilities`)),
  `image_digest` varchar(255) NOT NULL,
  `policy_fingerprint` char(64) NOT NULL,
  `writer_lease_owner` varchar(190) DEFAULT NULL,
  `writer_lease_expires_at` datetime DEFAULT NULL,
  `writer_fence` bigint NOT NULL,
  `expires_at` datetime NOT NULL,
  `error_code` varchar(100) DEFAULT NULL,
  `request_fingerprint` char(64) NOT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_chat_code_workspaces_request` (`owner_user_id`,`owner_project_id`,`request_fingerprint`),
  KEY `credential_id` (`credential_id`),
  KEY `idx_chat_code_workspaces_expiry` (`expires_at`,`lifecycle_status`),
  KEY `idx_chat_code_workspaces_owner_status` (`owner_user_id`,`owner_project_id`,`lifecycle_status`),
  CONSTRAINT `chat_code_workspaces_ibfk_1` FOREIGN KEY (`credential_id`) REFERENCES `chat_git_credentials` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB;

CREATE TABLE `chat_commands` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `owner_user_id` varchar(64) NOT NULL,
  `project_id` varchar(64) NOT NULL,
  `slug` varchar(100) NOT NULL,
  `prompt_template_ciphertext` mediumtext NOT NULL,
  `argument_hint` varchar(500) DEFAULT NULL,
  `agent_id` bigint DEFAULT NULL,
  `skill_ids` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`skill_ids`)),
  `execution_mode` varchar(10) NOT NULL,
  `is_active` tinyint NOT NULL,
  `content_hash` char(64) NOT NULL,
  `source_package_id` char(36) DEFAULT NULL,
  `source_package_version` varchar(64) DEFAULT NULL,
  `managed_by_package` tinyint NOT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_chat_commands_project_slug` (`project_id`,`slug`),
  KEY `agent_id` (`agent_id`),
  KEY `idx_chat_commands_owner_project` (`owner_user_id`,`project_id`,`is_active`),
  CONSTRAINT `chat_commands_ibfk_1` FOREIGN KEY (`agent_id`) REFERENCES `chat_agents` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB;

CREATE TABLE `chat_context_checkpoints` (
  `id` char(36) NOT NULL,
  `run_id` char(36) NOT NULL,
  `conversation_id` char(36) DEFAULT NULL,
  `source_anchor_message_id` bigint DEFAULT NULL,
  `source_hashes` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`source_hashes`)),
  `summary_ciphertext` mediumtext NOT NULL,
  `token_estimate` int NOT NULL,
  `context_limit` int NOT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `temp_thread_id` char(36) DEFAULT NULL,
  `source_message_ids` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`source_message_ids`)),
  `source_message_count` int NOT NULL DEFAULT 0,
  `previous_checkpoint_id` char(36) DEFAULT NULL,
  `context_metadata` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`context_metadata`)),
  PRIMARY KEY (`id`),
  KEY `run_id` (`run_id`),
  KEY `source_anchor_message_id` (`source_anchor_message_id`),
  KEY `fk_chat_context_checkpoints_previous` (`previous_checkpoint_id`),
  KEY `idx_chat_context_checkpoints_temp_created` (`temp_thread_id`,`created_at`),
  KEY `idx_chat_context_checkpoints_conversation_anchor` (`conversation_id`,`source_anchor_message_id`),
  CONSTRAINT `chat_context_checkpoints_ibfk_1` FOREIGN KEY (`run_id`) REFERENCES `chat_runs` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chat_context_checkpoints_ibfk_2` FOREIGN KEY (`conversation_id`) REFERENCES `chat_conversations` (`id`) ON DELETE SET NULL,
  CONSTRAINT `chat_context_checkpoints_ibfk_3` FOREIGN KEY (`source_anchor_message_id`) REFERENCES `chat_messages` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_chat_context_checkpoints_previous` FOREIGN KEY (`previous_checkpoint_id`) REFERENCES `chat_context_checkpoints` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_chat_context_checkpoints_temp_thread` FOREIGN KEY (`temp_thread_id`) REFERENCES `chat_temp_threads` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE `chat_conversation_active_path` (
  `conversation_id` char(36) NOT NULL,
  `position` bigint NOT NULL,
  `message_id` bigint NOT NULL,
  PRIMARY KEY (`conversation_id`,`position`),
  UNIQUE KEY `uq_chat_conversation_active_path_message` (`conversation_id`,`message_id`),
  KEY `idx_chat_active_path_message` (`message_id`),
  CONSTRAINT `fk_chat_active_path_conversation` FOREIGN KEY (`conversation_id`) REFERENCES `chat_conversations` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_chat_active_path_message` FOREIGN KEY (`message_id`) REFERENCES `chat_messages` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chk_chat_active_path_position` CHECK (`position` >= 0)
) ENGINE=InnoDB;

CREATE TABLE `chat_conversation_messages` (
  `conversation_id` char(36) NOT NULL,
  `message_id` bigint NOT NULL,
  PRIMARY KEY (`conversation_id`,`message_id`),
  KEY `idx_chat_conversation_messages_message` (`message_id`),
  CONSTRAINT `fk_chat_membership_conversation` FOREIGN KEY (`conversation_id`) REFERENCES `chat_conversations` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_chat_membership_message` FOREIGN KEY (`message_id`) REFERENCES `chat_messages` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE `chat_conversations` (
  `id` char(36) NOT NULL,
  `project_id` varchar(64) NOT NULL,
  `user_id` varchar(64) NOT NULL,
  `title` text DEFAULT NULL,
  `model_name` varchar(190) DEFAULT NULL,
  `active_leaf_id` bigint DEFAULT NULL,
  `parent_conversation_id` char(36) DEFAULT NULL,
  `forked_from_message_id` bigint DEFAULT NULL,
  `workspace_id` bigint DEFAULT NULL,
  `code_workspace_id` char(36) DEFAULT NULL,
  `lifecycle_status` varchar(20) NOT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `title_source` varchar(20) NOT NULL DEFAULT 'legacy',
  `title_status` varchar(20) NOT NULL DEFAULT 'idle',
  `title_revision` bigint NOT NULL DEFAULT 0,
  `history_revision` bigint NOT NULL DEFAULT 0,
  `history_index_ready` tinyint NOT NULL DEFAULT 0,
  `graph_id` char(36) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `code_workspace_id` (`code_workspace_id`),
  KEY `idx_chat_conversations_graph` (`graph_id`),
  KEY `idx_chat_conversations_owner` (`project_id`,`user_id`),
  KEY `idx_chat_conversations_updated` (`updated_at`),
  KEY `idx_chat_conversations_user_updated` (`user_id`,`updated_at`),
  CONSTRAINT `chat_conversations_ibfk_1` FOREIGN KEY (`code_workspace_id`) REFERENCES `chat_code_workspaces` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_chat_conversations_graph` FOREIGN KEY (`graph_id`) REFERENCES `chat_message_graphs` (`id`)
) ENGINE=InnoDB;

CREATE TABLE `chat_custom_tools` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `scope` varchar(10) NOT NULL,
  `owner_user_id` varchar(64) DEFAULT NULL,
  `owner_project_id` varchar(64) DEFAULT NULL,
  `project_id` varchar(64) DEFAULT NULL,
  `name` varchar(64) NOT NULL,
  `description` varchar(500) NOT NULL,
  `method` varchar(10) NOT NULL,
  `url` varchar(500) NOT NULL,
  `params_schema` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`params_schema`)),
  `timeout_seconds` int NOT NULL,
  `effect` varchar(30) NOT NULL,
  `config_version` bigint NOT NULL,
  `source_package_id` char(36) DEFAULT NULL,
  `source_package_version` varchar(64) DEFAULT NULL,
  `managed_by_package` tinyint NOT NULL,
  `is_active` tinyint NOT NULL,
  `load_policy` varchar(16) NOT NULL DEFAULT 'on_demand',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_chat_custom_tools_project` (`project_id`),
  KEY `idx_chat_tool_owner` (`owner_user_id`),
  KEY `idx_chat_tool_scope` (`scope`)
) ENGINE=InnoDB;

CREATE TABLE `chat_delegation_calls` (
  `id` char(36) NOT NULL,
  `group_id` char(36) NOT NULL,
  `parent_run_id` char(36) NOT NULL,
  `call_id` varchar(190) NOT NULL,
  `fingerprint` char(64) NOT NULL,
  `ordinal` int NOT NULL,
  `child_run_id` char(36) DEFAULT NULL,
  `state` varchar(20) NOT NULL DEFAULT 'prepared',
  `result_payload` mediumtext DEFAULT NULL,
  `created_at` datetime(6) NOT NULL DEFAULT current_timestamp(6),
  `updated_at` datetime(6) NOT NULL DEFAULT current_timestamp(6) ON UPDATE current_timestamp(6),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_delegation_call_identity` (`parent_run_id`,`call_id`),
  KEY `idx_delegation_call_child` (`child_run_id`),
  KEY `fk_delegation_call_group` (`group_id`),
  CONSTRAINT `fk_delegation_call_child` FOREIGN KEY (`child_run_id`) REFERENCES `chat_runs` (`id`),
  CONSTRAINT `fk_delegation_call_group` FOREIGN KEY (`group_id`) REFERENCES `chat_delegation_groups` (`id`),
  CONSTRAINT `fk_delegation_call_parent` FOREIGN KEY (`parent_run_id`) REFERENCES `chat_runs` (`id`)
) ENGINE=InnoDB;

CREATE TABLE `chat_delegation_groups` (
  `id` char(36) NOT NULL,
  `parent_run_id` char(36) NOT NULL,
  `model_segment_id` varchar(190) NOT NULL,
  `checkpoint_ns` varchar(190) DEFAULT NULL,
  `checkpoint_id` varchar(190) DEFAULT NULL,
  `state` varchar(20) NOT NULL DEFAULT 'prepared',
  `join_segment_id` varchar(190) DEFAULT NULL,
  `created_at` datetime(6) NOT NULL DEFAULT current_timestamp(6),
  `updated_at` datetime(6) NOT NULL DEFAULT current_timestamp(6) ON UPDATE current_timestamp(6),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_delegation_group_segment` (`parent_run_id`,`model_segment_id`),
  UNIQUE KEY `uq_delegation_group_join` (`join_segment_id`),
  KEY `idx_delegation_group_state` (`state`,`parent_run_id`),
  CONSTRAINT `fk_delegation_group_parent` FOREIGN KEY (`parent_run_id`) REFERENCES `chat_runs` (`id`)
) ENGINE=InnoDB;

CREATE TABLE `chat_extension_package_components` (
  `install_id` char(36) NOT NULL,
  `component_type` varchar(30) NOT NULL,
  `component_ref` varchar(100) NOT NULL,
  `materialized_id` bigint DEFAULT NULL,
  `content_hash` char(64) NOT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`install_id`,`component_type`,`component_ref`),
  CONSTRAINT `chat_extension_package_components_ibfk_1` FOREIGN KEY (`install_id`) REFERENCES `chat_extension_package_installs` (`id`)
) ENGINE=InnoDB;

CREATE TABLE `chat_extension_package_installs` (
  `id` char(36) NOT NULL,
  `package_id` char(36) NOT NULL,
  `package_name` varchar(100) NOT NULL,
  `owner_user_id` varchar(64) NOT NULL,
  `owner_project_id` varchar(64) NOT NULL,
  `status` varchar(20) NOT NULL,
  `installed_version` varchar(64) NOT NULL,
  `request_fingerprint` char(64) NOT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_chat_extension_install_request` (`owner_user_id`,`owner_project_id`,`request_fingerprint`),
  UNIQUE KEY `uq_chat_extension_install_project_name` (`owner_user_id`,`owner_project_id`,`package_name`),
  KEY `package_id` (`package_id`),
  KEY `idx_chat_extension_installs_owner_status` (`owner_user_id`,`owner_project_id`,`status`),
  CONSTRAINT `chat_extension_package_installs_ibfk_1` FOREIGN KEY (`package_id`) REFERENCES `chat_extension_packages` (`id`)
) ENGINE=InnoDB;

CREATE TABLE `chat_extension_packages` (
  `id` char(36) NOT NULL,
  `name` varchar(100) NOT NULL,
  `version` varchar(64) NOT NULL,
  `description` varchar(1000) NOT NULL,
  `manifest_ciphertext` mediumtext NOT NULL,
  `manifest_hash` char(64) NOT NULL,
  `status` varchar(20) NOT NULL,
  `created_by_user_id` varchar(64) NOT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_chat_extension_packages_name_version` (`name`,`version`),
  KEY `idx_chat_extension_packages_status` (`status`,`name`)
) ENGINE=InnoDB;

CREATE TABLE `chat_gateway_device_grants` (
  `id` char(36) NOT NULL,
  `device_code_hash` char(64) NOT NULL,
  `user_code_hash` char(64) NOT NULL,
  `client_id_hash` char(64) NOT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'pending',
  `created_at` datetime(6) NOT NULL,
  `expires_at` datetime(6) NOT NULL,
  `next_poll_at` datetime(6) NOT NULL,
  `poll_interval_seconds` int NOT NULL,
  `owner_user_id` varchar(64) DEFAULT NULL,
  `owner_project_id` varchar(64) DEFAULT NULL,
  `issued_api_key_id` bigint DEFAULT NULL,
  `approved_at` datetime(6) DEFAULT NULL,
  `denied_at` datetime(6) DEFAULT NULL,
  `consumed_at` datetime(6) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_chat_gateway_device_code_hash` (`device_code_hash`),
  UNIQUE KEY `uq_chat_gateway_user_code_hash` (`user_code_hash`),
  KEY `fk_chat_gateway_issued_api_key` (`issued_api_key_id`),
  KEY `idx_chat_gateway_device_expiry` (`status`,`expires_at`),
  KEY `idx_chat_gateway_device_owner` (`owner_project_id`,`owner_user_id`,`status`),
  CONSTRAINT `fk_chat_gateway_issued_api_key` FOREIGN KEY (`issued_api_key_id`) REFERENCES `chat_api_keys` (`id`) ON DELETE SET NULL,
  CONSTRAINT `chk_chat_gateway_device_status` CHECK (`status` in ('pending','approved','denied','consumed')),
  CONSTRAINT `chk_chat_gateway_device_poll_interval` CHECK (`poll_interval_seconds` between 1 and 60)
) ENGINE=InnoDB;

CREATE TABLE `chat_git_credentials` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `owner_user_id` varchar(64) NOT NULL,
  `owner_project_id` varchar(64) NOT NULL,
  `host` varchar(255) NOT NULL,
  `username` varchar(255) DEFAULT NULL,
  `token_ciphertext` mediumtext NOT NULL,
  `credential_version` bigint NOT NULL,
  `revoked_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_chat_git_credentials_owner_host` (`owner_user_id`,`owner_project_id`,`host`)
) ENGINE=InnoDB;

CREATE TABLE `chat_input_derivations` (
  `id` char(36) NOT NULL,
  `message_id` bigint DEFAULT NULL,
  `temp_thread_id` char(36) DEFAULT NULL,
  `turn_ordinal` int DEFAULT NULL,
  `part_index` int NOT NULL,
  `asset_id` char(36) NOT NULL,
  `asset_sha256` char(64) NOT NULL,
  `kind` varchar(30) NOT NULL,
  `content` mediumtext DEFAULT NULL,
  `producer_model` varchar(190) DEFAULT NULL,
  `producer_version` varchar(190) DEFAULT NULL,
  `usage_segment_id` varchar(190) DEFAULT NULL,
  `status` varchar(20) NOT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_chat_input_derivation` (`message_id`,`temp_thread_id`,`turn_ordinal`,`part_index`,`asset_sha256`,`kind`),
  KEY `asset_id` (`asset_id`),
  CONSTRAINT `chat_input_derivations_ibfk_1` FOREIGN KEY (`message_id`) REFERENCES `chat_messages` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chat_input_derivations_ibfk_2` FOREIGN KEY (`asset_id`) REFERENCES `chat_assets` (`id`)
) ENGINE=InnoDB;

CREATE TABLE `chat_jobs` (
  `id` char(36) NOT NULL,
  `kind` varchar(40) NOT NULL,
  `run_id` char(36) DEFAULT NULL,
  `conversation_id` char(36) DEFAULT NULL,
  `memory_id` bigint DEFAULT NULL,
  `asset_id` char(36) DEFAULT NULL,
  `payload` mediumtext DEFAULT NULL,
  `progress` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`progress`)),
  `status` varchar(20) NOT NULL,
  `lease_owner` varchar(190) DEFAULT NULL,
  `lease_expires_at` datetime DEFAULT NULL,
  `attempts` int NOT NULL,
  `next_at` datetime NOT NULL,
  `error_code` varchar(100) DEFAULT NULL,
  `idempotency_key` varchar(190) NOT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idempotency_key` (`idempotency_key`),
  KEY `run_id` (`run_id`),
  KEY `conversation_id` (`conversation_id`),
  KEY `asset_id` (`asset_id`),
  KEY `idx_chat_jobs_owner_lease` (`lease_owner`,`status`,`lease_expires_at`),
  KEY `idx_chat_jobs_claim` (`status`,`next_at`),
  CONSTRAINT `chat_jobs_ibfk_1` FOREIGN KEY (`run_id`) REFERENCES `chat_runs` (`id`) ON DELETE SET NULL,
  CONSTRAINT `chat_jobs_ibfk_2` FOREIGN KEY (`conversation_id`) REFERENCES `chat_conversations` (`id`) ON DELETE SET NULL,
  CONSTRAINT `chat_jobs_ibfk_3` FOREIGN KEY (`asset_id`) REFERENCES `chat_assets` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB;

CREATE TABLE `chat_mcp_activations` (
  `mcp_server_id` bigint NOT NULL,
  `owner_user_id` varchar(64) NOT NULL,
  `owner_project_id` varchar(64) NOT NULL,
  `is_active` tinyint NOT NULL DEFAULT 0,
  `config_version` bigint NOT NULL,
  `generation` bigint NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`mcp_server_id`,`owner_user_id`,`owner_project_id`),
  KEY `idx_chat_mcp_activation_owner` (`owner_user_id`,`owner_project_id`),
  CONSTRAINT `fk_chat_mcp_activation_server` FOREIGN KEY (`mcp_server_id`) REFERENCES `chat_mcp_servers` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE `chat_mcp_credentials` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `mcp_server_id` bigint NOT NULL,
  `owner_user_id` varchar(64) NOT NULL,
  `owner_project_id` varchar(64) NOT NULL,
  `encrypted_values` text NOT NULL,
  `created_at` datetime(6) NOT NULL DEFAULT current_timestamp(6),
  `updated_at` datetime(6) NOT NULL DEFAULT current_timestamp(6) ON UPDATE current_timestamp(6),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_chat_mcp_cred` (`mcp_server_id`,`owner_user_id`,`owner_project_id`),
  KEY `idx_chat_mcp_cred_owner` (`owner_user_id`,`owner_project_id`)
) ENGINE=InnoDB;

CREATE TABLE `chat_mcp_oauth_connections` (
  `id` char(36) NOT NULL,
  `mcp_server_id` bigint NOT NULL,
  `owner_user_id` varchar(64) NOT NULL,
  `owner_project_id` varchar(64) NOT NULL,
  `encrypted_tokens` text NOT NULL,
  `credential_version` bigint NOT NULL,
  `status` varchar(12) NOT NULL,
  `expires_at` datetime DEFAULT NULL,
  `server_config_version` bigint NOT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_chat_mcp_oauth_connection` (`mcp_server_id`,`owner_user_id`,`owner_project_id`),
  KEY `idx_chat_mcp_oauth_connection_owner` (`owner_user_id`,`owner_project_id`,`status`)
) ENGINE=InnoDB;

CREATE TABLE `chat_mcp_oauth_requests` (
  `id` char(36) NOT NULL,
  `state_hash` char(64) NOT NULL,
  `mcp_server_id` bigint NOT NULL,
  `owner_user_id` varchar(64) NOT NULL,
  `owner_project_id` varchar(64) NOT NULL,
  `encrypted_payload` text NOT NULL,
  `server_config_version` bigint NOT NULL,
  `status` varchar(12) NOT NULL,
  `expires_at` datetime NOT NULL,
  `completed_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `state_hash` (`state_hash`),
  KEY `idx_chat_mcp_oauth_request_expiry` (`expires_at`,`status`)
) ENGINE=InnoDB;

CREATE TABLE `chat_mcp_servers` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `scope` varchar(10) NOT NULL,
  `owner_user_id` varchar(64) DEFAULT NULL,
  `owner_project_id` varchar(64) DEFAULT NULL,
  `project_id` varchar(64) DEFAULT NULL,
  `name` varchar(100) NOT NULL,
  `transport` varchar(20) NOT NULL,
  `url` varchar(500) DEFAULT NULL,
  `command` varchar(500) DEFAULT NULL,
  `headers` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`headers`)),
  `encrypted_headers` text DEFAULT NULL,
  `auth_mode` varchar(12) NOT NULL,
  `oauth_scopes` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`oauth_scopes`)),
  `oauth_client_id` varchar(512) DEFAULT NULL,
  `encrypted_oauth_client_secret` text DEFAULT NULL,
  `tool_effect_overrides` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`tool_effect_overrides`)),
  `config_version` bigint NOT NULL,
  `source_package_id` char(36) DEFAULT NULL,
  `source_package_version` varchar(64) DEFAULT NULL,
  `managed_by_package` tinyint NOT NULL,
  `is_active` tinyint NOT NULL,
  `load_policy` varchar(16) NOT NULL DEFAULT 'on_demand',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `auth_requirements` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`auth_requirements`)),
  PRIMARY KEY (`id`),
  KEY `idx_chat_mcp_owner` (`owner_user_id`),
  KEY `idx_chat_mcp_scope` (`scope`),
  KEY `idx_chat_mcp_servers_project` (`project_id`)
) ENGINE=InnoDB;

CREATE TABLE `chat_memories` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` varchar(64) NOT NULL,
  `project_id` varchar(64) DEFAULT NULL,
  `workspace_id` bigint DEFAULT NULL,
  `scope` varchar(20) NOT NULL,
  `category` varchar(32) NOT NULL,
  `confidence` decimal(5,4) DEFAULT NULL,
  `expires_at` datetime DEFAULT NULL,
  `status` varchar(20) NOT NULL,
  `extraction_status` varchar(20) DEFAULT NULL,
  `content` mediumtext DEFAULT NULL,
  `is_active` tinyint NOT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_chat_memories_scope` (`user_id`,`project_id`,`workspace_id`,`status`,`is_active`),
  KEY `idx_chat_memories_user` (`user_id`),
  CONSTRAINT `chk_chat_memory_scope` CHECK (`scope` = 'account' and `project_id` is null and `workspace_id` is null or `scope` = 'project' and `project_id` is not null and `workspace_id` is null or `scope` = 'workspace' and `project_id` is not null and `workspace_id` is not null)
) ENGINE=InnoDB;

CREATE TABLE `chat_memory_outbox` (
  `change_seq` bigint NOT NULL AUTO_INCREMENT,
  `event_key` varchar(190) NOT NULL,
  `memory_id` bigint NOT NULL,
  `mutation` varchar(20) NOT NULL,
  `content_hash` char(64) NOT NULL,
  `required_generations` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`required_generations`)),
  `applied_generations` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`applied_generations`)),
  `status` varchar(20) NOT NULL,
  `lease_owner` varchar(190) DEFAULT NULL,
  `lease_expires_at` datetime DEFAULT NULL,
  `attempts` int NOT NULL,
  `error_code` varchar(100) DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`change_seq`),
  UNIQUE KEY `event_key` (`event_key`),
  KEY `memory_id` (`memory_id`),
  KEY `idx_chat_memory_outbox_owner_lease` (`lease_owner`,`status`,`lease_expires_at`),
  KEY `idx_chat_memory_outbox_claim` (`status`,`change_seq`),
  CONSTRAINT `chat_memory_outbox_ibfk_1` FOREIGN KEY (`memory_id`) REFERENCES `chat_memories` (`id`)
) ENGINE=InnoDB;

CREATE TABLE `chat_memory_owner_locks` (
  `user_id` varchar(64) NOT NULL,
  `project_id` varchar(64) NOT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`user_id`,`project_id`)
) ENGINE=InnoDB;

CREATE TABLE `chat_memory_provenance` (
  `memory_id` bigint NOT NULL,
  `message_id` bigint NOT NULL,
  `source_type` varchar(30) NOT NULL,
  `conversation_id` char(36) NOT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`memory_id`,`message_id`,`source_type`),
  KEY `message_id` (`message_id`),
  KEY `conversation_id` (`conversation_id`),
  CONSTRAINT `chat_memory_provenance_ibfk_1` FOREIGN KEY (`memory_id`) REFERENCES `chat_memories` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chat_memory_provenance_ibfk_2` FOREIGN KEY (`message_id`) REFERENCES `chat_messages` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chat_memory_provenance_ibfk_3` FOREIGN KEY (`conversation_id`) REFERENCES `chat_conversations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE `chat_message_assets` (
  `message_id` bigint NOT NULL,
  `asset_id` char(36) NOT NULL,
  `part_index` int NOT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`message_id`,`asset_id`),
  UNIQUE KEY `uq_chat_message_assets_part` (`message_id`,`part_index`),
  KEY `asset_id` (`asset_id`),
  CONSTRAINT `chat_message_assets_ibfk_1` FOREIGN KEY (`message_id`) REFERENCES `chat_messages` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chat_message_assets_ibfk_2` FOREIGN KEY (`asset_id`) REFERENCES `chat_assets` (`id`)
) ENGINE=InnoDB;

CREATE TABLE `chat_message_graphs` (
  `id` char(36) NOT NULL,
  `user_id` varchar(64) NOT NULL,
  `project_id` varchar(64) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_chat_message_graphs_owner` (`project_id`,`user_id`)
) ENGINE=InnoDB;

CREATE TABLE `chat_messages` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `conversation_id` char(36) DEFAULT NULL,
  `role` varchar(20) NOT NULL,
  `parent_id` bigint DEFAULT NULL,
  `content` mediumtext DEFAULT NULL,
  `tool_calls` mediumtext DEFAULT NULL,
  `citations` mediumtext DEFAULT NULL,
  `reasoning` mediumtext DEFAULT NULL,
  `attachments` mediumtext DEFAULT NULL,
  `parts` mediumtext DEFAULT NULL,
  `parts_version` int DEFAULT NULL,
  `status` varchar(20) NOT NULL,
  `token_prompt` int NOT NULL,
  `token_completion` int NOT NULL,
  `model_name` varchar(190) DEFAULT NULL,
  `created_at` datetime(6) NOT NULL,
  `created_at_local` datetime(6) DEFAULT NULL,
  `created_timezone` varchar(64) DEFAULT NULL,
  `graph_id` char(36) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_chat_messages_branch` (`conversation_id`,`parent_id`,`role`,`created_at`,`id`),
  KEY `idx_chat_messages_conversation_id` (`conversation_id`,`id`),
  KEY `idx_chat_messages_graph` (`graph_id`),
  KEY `idx_chat_messages_graph_branch` (`graph_id`,`parent_id`,`role`,`created_at`,`id`),
  KEY `idx_chat_messages_conversation` (`conversation_id`,`created_at`),
  KEY `idx_chat_messages_parent` (`parent_id`),
  CONSTRAINT `fk_chat_messages_graph` FOREIGN KEY (`graph_id`) REFERENCES `chat_message_graphs` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_chat_messages_origin_conversation` FOREIGN KEY (`conversation_id`) REFERENCES `chat_conversations` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB;

CREATE TABLE `chat_model_call_reservations` (
  `run_id` char(36) NOT NULL,
  `segment_id` varchar(190) NOT NULL,
  `bound_credits` decimal(18,8) NOT NULL,
  `actual_credits` decimal(18,8) DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'reserved',
  `created_at` datetime(6) NOT NULL DEFAULT current_timestamp(6),
  `settled_at` datetime(6) DEFAULT NULL,
  PRIMARY KEY (`run_id`,`segment_id`),
  CONSTRAINT `fk_model_call_reservation_run` FOREIGN KEY (`run_id`) REFERENCES `chat_runs` (`id`),
  CONSTRAINT `ck_model_call_bound` CHECK (`bound_credits` >= 0),
  CONSTRAINT `ck_model_call_actual` CHECK (`actual_credits` is null or `actual_credits` >= 0)
) ENGINE=InnoDB;

CREATE TABLE `chat_plugin_bindings` (
  `id` char(36) NOT NULL,
  `kind` varchar(10) NOT NULL,
  `plugin_id` varchar(190) NOT NULL,
  `export_key` varchar(128) NOT NULL,
  `name` varchar(190) NOT NULL,
  `scope` varchar(10) NOT NULL,
  `owner_user_id` varchar(64) DEFAULT NULL,
  `owner_project_id` varchar(64) DEFAULT NULL,
  `encrypted_config` mediumtext NOT NULL,
  `config_version` bigint NOT NULL DEFAULT 1,
  `is_active` tinyint NOT NULL DEFAULT 1,
  `created_at` datetime(6) NOT NULL DEFAULT current_timestamp(6),
  `updated_at` datetime(6) NOT NULL DEFAULT current_timestamp(6) ON UPDATE current_timestamp(6),
  PRIMARY KEY (`id`),
  KEY `idx_plugin_binding_catalog` (`scope`,`owner_user_id`,`owner_project_id`,`is_active`),
  CONSTRAINT `ck_plugin_binding_kind` CHECK (`kind` in ('tool','skill')),
  CONSTRAINT `ck_plugin_binding_owner` CHECK (`scope` = 'global' and `owner_user_id` is null and `owner_project_id` is null or `scope` = 'user' and `owner_user_id` is not null and `owner_project_id` is not null)
) ENGINE=InnoDB;

CREATE TABLE `chat_project_agent_quotas` (
  `project_id` varchar(64) NOT NULL,
  `max_active_children` int NOT NULL DEFAULT 0,
  `max_active_sandboxes` int NOT NULL DEFAULT 0,
  `max_sandbox_seconds` int NOT NULL DEFAULT 0,
  `max_credit_reservation` decimal(18,8) NOT NULL DEFAULT 0.00000000,
  `active_children` int NOT NULL DEFAULT 0,
  `active_sandboxes` int NOT NULL DEFAULT 0,
  `sandbox_seconds_reserved` int NOT NULL DEFAULT 0,
  `credits_reserved` decimal(18,8) NOT NULL DEFAULT 0.00000000,
  `updated_at` datetime(6) NOT NULL DEFAULT current_timestamp(6) ON UPDATE current_timestamp(6),
  PRIMARY KEY (`project_id`)
) ENGINE=InnoDB;

CREATE TABLE `chat_provider_usage` (
  `event_id` varchar(64) NOT NULL,
  `provider_account_id` bigint NOT NULL,
  `provider_credential_id` bigint NOT NULL,
  `provider_id` bigint NOT NULL,
  `provider_credential_generation` bigint NOT NULL,
  `provider_backend` varchar(40) DEFAULT NULL,
  `provider_backend_version` varchar(100) DEFAULT NULL,
  `prompt_tokens` bigint NOT NULL DEFAULT 0,
  `completion_tokens` bigint NOT NULL DEFAULT 0,
  `raw_cost` decimal(20,10) NOT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`event_id`,`provider_account_id`,`provider_credential_id`),
  KEY `idx_provider_usage_account` (`provider_account_id`,`created_at`),
  CONSTRAINT `chk_provider_usage_nonnegative` CHECK (`raw_cost` >= 0 and `prompt_tokens` >= 0 and `completion_tokens` >= 0)
) ENGINE=InnoDB;

CREATE TABLE `chat_quota_policies` (
  `id` int NOT NULL,
  `default_monthly_credit_limit` decimal(18,8) NOT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  CONSTRAINT `chk_chat_quota_policies_singleton` CHECK (`id` = 1),
  CONSTRAINT `chk_chat_quota_policies_default_monthly` CHECK (`default_monthly_credit_limit` >= 0)
) ENGINE=InnoDB;

CREATE TABLE `chat_resource_operations` (
  `id` char(36) NOT NULL,
  `resource_id` char(36) NOT NULL,
  `generation` int NOT NULL,
  `action` varchar(30) NOT NULL,
  `request_status` varchar(20) NOT NULL DEFAULT 'claimed',
  `owner` varchar(190) NOT NULL,
  `fence` bigint NOT NULL,
  `provider_request_id` varchar(190) DEFAULT NULL,
  `attempts` int NOT NULL DEFAULT 0,
  `retry_at` datetime(6) DEFAULT NULL,
  `error_code` varchar(100) DEFAULT NULL,
  `created_at` datetime(6) NOT NULL DEFAULT current_timestamp(6),
  `updated_at` datetime(6) NOT NULL DEFAULT current_timestamp(6) ON UPDATE current_timestamp(6),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_resource_operation_identity` (`resource_id`,`generation`,`action`),
  KEY `idx_resource_operation_retry` (`request_status`,`retry_at`),
  CONSTRAINT `fk_resource_operation_resource` FOREIGN KEY (`resource_id`) REFERENCES `chat_runtime_resources` (`id`)
) ENGINE=InnoDB;

CREATE TABLE `chat_run_assets` (
  `run_id` char(36) NOT NULL,
  `asset_id` char(36) NOT NULL,
  `purpose` varchar(30) NOT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`run_id`,`asset_id`,`purpose`),
  KEY `asset_id` (`asset_id`),
  CONSTRAINT `chat_run_assets_ibfk_1` FOREIGN KEY (`run_id`) REFERENCES `chat_runs` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chat_run_assets_ibfk_2` FOREIGN KEY (`asset_id`) REFERENCES `chat_assets` (`id`)
) ENGINE=InnoDB;

CREATE TABLE `chat_run_events` (
  `run_id` char(36) NOT NULL,
  `seq` bigint NOT NULL,
  `event_type` varchar(40) NOT NULL,
  `payload` mediumtext NOT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`run_id`,`seq`),
  CONSTRAINT `chat_run_events_ibfk_1` FOREIGN KEY (`run_id`) REFERENCES `chat_runs` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE `chat_run_interactions` (
  `run_id` char(36) NOT NULL,
  `id` char(36) NOT NULL,
  `status` varchar(20) NOT NULL,
  `request_ciphertext` mediumtext NOT NULL,
  `response_ciphertext` mediumtext DEFAULT NULL,
  `response_schema` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`response_schema`)),
  `requested_at` datetime NOT NULL,
  `decided_at` datetime DEFAULT NULL,
  `decided_by_user_id` varchar(64) DEFAULT NULL,
  `expires_at` datetime NOT NULL,
  PRIMARY KEY (`run_id`,`id`),
  KEY `idx_chat_run_interactions_pending_expiry` (`status`,`expires_at`),
  CONSTRAINT `chat_run_interactions_ibfk_1` FOREIGN KEY (`run_id`) REFERENCES `chat_runs` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE `chat_run_providers` (
  `run_id` char(36) NOT NULL,
  `purpose` varchar(30) NOT NULL,
  `provider_id` bigint DEFAULT NULL,
  `model_id` bigint DEFAULT NULL,
  `provider_label` varchar(190) NOT NULL,
  `model_label` varchar(190) NOT NULL,
  `config_version_hash` varchar(128) NOT NULL,
  `created_at` datetime NOT NULL,
  `provider_account_id` bigint DEFAULT NULL,
  `provider_credential_id` bigint DEFAULT NULL,
  `provider_credential_generation` bigint DEFAULT NULL,
  `provider_backend` varchar(40) DEFAULT NULL,
  `provider_backend_version` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`run_id`,`purpose`),
  KEY `provider_id` (`provider_id`),
  KEY `model_id` (`model_id`),
  CONSTRAINT `chat_run_providers_ibfk_1` FOREIGN KEY (`run_id`) REFERENCES `chat_runs` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chat_run_providers_ibfk_2` FOREIGN KEY (`provider_id`) REFERENCES `llm_providers` (`id`) ON DELETE SET NULL,
  CONSTRAINT `chat_run_providers_ibfk_3` FOREIGN KEY (`model_id`) REFERENCES `llm_models` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB;

CREATE TABLE `chat_run_segments` (
  `run_id` char(36) NOT NULL,
  `segment_id` varchar(190) NOT NULL,
  `ordinal` int NOT NULL,
  `endpoint` varchar(40) NOT NULL,
  `kind` varchar(40) NOT NULL,
  `boundary_key` varchar(255) DEFAULT NULL,
  `turn_ordinal` int DEFAULT NULL,
  `call_id` varchar(190) DEFAULT NULL,
  `status` varchar(30) NOT NULL,
  `provider_started_at` datetime DEFAULT NULL,
  `result_payload` mediumtext DEFAULT NULL,
  `usage_payload` mediumtext DEFAULT NULL,
  `started_event_seq` bigint DEFAULT NULL,
  `completed_event_seq` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `completed_at` datetime DEFAULT NULL,
  PRIMARY KEY (`run_id`,`segment_id`),
  UNIQUE KEY `uq_chat_run_segments_ordinal` (`run_id`,`ordinal`),
  UNIQUE KEY `uq_chat_run_segments_boundary` (`run_id`,`boundary_key`),
  CONSTRAINT `chat_run_segments_ibfk_1` FOREIGN KEY (`run_id`) REFERENCES `chat_runs` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE `chat_run_turns` (
  `run_id` char(36) NOT NULL,
  `ordinal` int NOT NULL,
  `assistant_message_id` bigint DEFAULT NULL,
  `message_event_seq` bigint DEFAULT NULL,
  `completion_event_seq` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`run_id`,`ordinal`),
  UNIQUE KEY `uq_chat_run_turn_message_event` (`run_id`,`message_event_seq`),
  KEY `assistant_message_id` (`assistant_message_id`),
  CONSTRAINT `chat_run_turns_ibfk_1` FOREIGN KEY (`run_id`) REFERENCES `chat_runs` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chat_run_turns_ibfk_2` FOREIGN KEY (`assistant_message_id`) REFERENCES `chat_messages` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB;

CREATE TABLE `chat_runs` (
  `id` char(36) NOT NULL,
  `run_scope` varchar(20) NOT NULL,
  `conversation_id` char(36) DEFAULT NULL,
  `temp_thread_id` char(36) DEFAULT NULL,
  `user_message_id` bigint DEFAULT NULL,
  `assistant_message_id` bigint DEFAULT NULL,
  `project_id` varchar(64) NOT NULL,
  `user_id` varchar(64) NOT NULL,
  `model_name` varchar(190) NOT NULL,
  `agent_id` bigint DEFAULT NULL,
  `capability_snapshot` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`capability_snapshot`)),
  `pricing_snapshot` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`pricing_snapshot`)),
  `request_payload` mediumtext DEFAULT NULL,
  `client_request_id` char(36) NOT NULL,
  `request_fingerprint` varchar(128) NOT NULL,
  `fingerprint_version` int NOT NULL,
  `execution_protocol_version` int NOT NULL,
  `execution_mode` varchar(10) NOT NULL,
  `code_workspace_id` char(36) DEFAULT NULL,
  `parent_run_id` char(36) DEFAULT NULL,
  `root_run_id` char(36) DEFAULT NULL,
  `delegation_call_id` varchar(190) DEFAULT NULL,
  `depth` int NOT NULL,
  `policy_snapshot` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`policy_snapshot`)),
  `reservation_snapshot` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`reservation_snapshot`)),
  `status` varchar(30) NOT NULL,
  `last_seq` bigint NOT NULL,
  `current_ordinal` int NOT NULL,
  `lease_owner` varchar(190) DEFAULT NULL,
  `lease_expires_at` datetime DEFAULT NULL,
  `provider_started_at` datetime DEFAULT NULL,
  `cancel_requested_at` datetime DEFAULT NULL,
  `finalizer_lease_owner` varchar(190) DEFAULT NULL,
  `finalizer_lease_expires_at` datetime DEFAULT NULL,
  `reserved_credits` decimal(18,8) NOT NULL,
  `reservation_released_at` datetime DEFAULT NULL,
  `usage_reconciled_at` datetime DEFAULT NULL,
  `descendant_credit_ceiling` decimal(18,8) DEFAULT NULL,
  `descendant_credits_reserved` decimal(18,8) NOT NULL,
  `sandbox_seconds_ceiling` int DEFAULT NULL,
  `sandbox_seconds_reserved` int NOT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `source` varchar(10) NOT NULL,
  `api_key_id` bigint DEFAULT NULL,
  `run_kind` varchar(20) NOT NULL DEFAULT 'completion',
  `lease_fence` bigint NOT NULL DEFAULT 0,
  `assigned_resource_id` char(36) DEFAULT NULL,
  `runtime_pool_id` char(36) DEFAULT NULL,
  `required_plugin_digest` char(64) DEFAULT NULL,
  `credit_ceiling` decimal(18,8) DEFAULT NULL,
  `wall_time_seconds` int DEFAULT NULL,
  `deadline_at` datetime(6) DEFAULT NULL,
  `workload_class` varchar(20) NOT NULL DEFAULT 'online_text',
  `worker_pool_id` char(36) DEFAULT NULL,
  `worker_registration_id` char(36) DEFAULT NULL,
  `batch_id` char(36) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_chat_runs_idempotency` (`project_id`,`user_id`,`client_request_id`),
  UNIQUE KEY `uq_chat_runs_parent_delegation` (`parent_run_id`,`delegation_call_id`),
  KEY `assistant_message_id` (`assistant_message_id`),
  KEY `code_workspace_id` (`code_workspace_id`),
  KEY `idx_chat_runs_user_message_updated` (`user_message_id`,`updated_at`,`id`),
  KEY `idx_chat_runs_status_pool` (`status`,`runtime_pool_id`),
  KEY `idx_chat_runs_status_plugin_digest` (`status`,`required_plugin_digest`),
  KEY `idx_chat_runs_assigned_resource` (`assigned_resource_id`),
  KEY `idx_chat_runs_worker_pool_workload_status` (`worker_pool_id`,`workload_class`,`status`,`created_at`,`id`),
  KEY `idx_chat_runs_worker_registration_lease` (`worker_registration_id`,`status`,`lease_expires_at`),
  KEY `idx_chat_runs_batch_status` (`batch_id`,`status`),
  KEY `idx_chat_runs_conversation_status` (`conversation_id`,`status`),
  KEY `idx_chat_runs_owner_status` (`project_id`,`user_id`,`status`),
  KEY `idx_chat_runs_parent_status` (`parent_run_id`,`status`),
  KEY `idx_chat_runs_root_status` (`root_run_id`,`status`),
  KEY `idx_chat_runs_temp_status` (`temp_thread_id`,`status`),
  CONSTRAINT `chat_runs_ibfk_1` FOREIGN KEY (`conversation_id`) REFERENCES `chat_conversations` (`id`) ON DELETE SET NULL,
  CONSTRAINT `chat_runs_ibfk_2` FOREIGN KEY (`user_message_id`) REFERENCES `chat_messages` (`id`) ON DELETE SET NULL,
  CONSTRAINT `chat_runs_ibfk_3` FOREIGN KEY (`assistant_message_id`) REFERENCES `chat_messages` (`id`) ON DELETE SET NULL,
  CONSTRAINT `chat_runs_ibfk_4` FOREIGN KEY (`code_workspace_id`) REFERENCES `chat_code_workspaces` (`id`) ON DELETE SET NULL,
  CONSTRAINT `chat_runs_ibfk_5` FOREIGN KEY (`parent_run_id`) REFERENCES `chat_runs` (`id`),
  CONSTRAINT `chat_runs_ibfk_6` FOREIGN KEY (`root_run_id`) REFERENCES `chat_runs` (`id`),
  CONSTRAINT `ck_chat_runs_workload_class` CHECK (`workload_class` in ('online_text','online_media','batch','realtime'))
) ENGINE=InnoDB;

CREATE TABLE `chat_runtime_pools` (
  `id` char(36) NOT NULL,
  `deployment_id` varchar(64) NOT NULL,
  `name` varchar(64) NOT NULL,
  `role` varchar(10) NOT NULL,
  `backend` varchar(10) NOT NULL,
  `enabled` tinyint NOT NULL DEFAULT 0,
  `cloud_profile_id` varchar(190) DEFAULT NULL,
  `project_id` varchar(64) DEFAULT NULL,
  `region_name` varchar(190) DEFAULT NULL,
  `image_ref` varchar(255) NOT NULL,
  `profile_digest` char(64) NOT NULL,
  `min_replicas` int NOT NULL DEFAULT 0,
  `max_replicas` int NOT NULL DEFAULT 0,
  `slots_per_worker` int NOT NULL DEFAULT 1,
  `target_wait_seconds` int NOT NULL DEFAULT 10,
  `boot_timeout_seconds` int NOT NULL DEFAULT 600,
  `idle_seconds` int NOT NULL DEFAULT 300,
  `drain_seconds` int NOT NULL DEFAULT 300,
  `max_lifetime_seconds` int NOT NULL DEFAULT 1800,
  `db_connection_budget` int DEFAULT NULL,
  `ingress_pool_id` varchar(190) DEFAULT NULL,
  `ingress_vip` varchar(190) DEFAULT NULL,
  `desired_revision` bigint NOT NULL DEFAULT 1,
  `reconcile_lease_owner` varchar(190) DEFAULT NULL,
  `reconcile_lease_expires_at` datetime(6) DEFAULT NULL,
  `reconcile_fence` bigint NOT NULL DEFAULT 0,
  `low_demand_since` datetime(6) DEFAULT NULL,
  `high_demand_samples` int NOT NULL DEFAULT 0,
  `service_time_estimate_ms` int NOT NULL DEFAULT 30000,
  `created_at` datetime(6) NOT NULL DEFAULT current_timestamp(6),
  `updated_at` datetime(6) NOT NULL DEFAULT current_timestamp(6) ON UPDATE current_timestamp(6),
  `workload_class` varchar(20) DEFAULT NULL,
  `guest_profile_id` varchar(190) DEFAULT NULL,
  `guest_profile_digest` char(64) DEFAULT NULL,
  `max_surge` int NOT NULL DEFAULT 1,
  `desired_replicas` int NOT NULL DEFAULT 0,
  `ready_replicas` int NOT NULL DEFAULT 0,
  `provisioning_replicas` int NOT NULL DEFAULT 0,
  `draining_replicas` int NOT NULL DEFAULT 0,
  `queued_count` int NOT NULL DEFAULT 0,
  `oldest_queued_seconds` int DEFAULT NULL,
  `last_scale_reason` varchar(40) DEFAULT NULL,
  `last_reconciled_at` datetime(6) DEFAULT NULL,
  `service_time_cursor_at` datetime(6) DEFAULT NULL,
  `service_time_cursor_id` char(36) DEFAULT NULL,
  `cluster_profile_id` varchar(64) DEFAULT NULL,
  `namespace` varchar(63) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_runtime_pool_name` (`deployment_id`,`name`),
  CONSTRAINT `ck_runtime_pool_role` CHECK (`role` in ('api','worker','sandbox')),
  CONSTRAINT `ck_runtime_pool_replicas` CHECK (`min_replicas` >= 0 and `max_replicas` >= `min_replicas`),
  CONSTRAINT `ck_runtime_pool_workload_class` CHECK (`workload_class` in ('online_text','online_media','batch')),
  CONSTRAINT `ck_runtime_pool_backend` CHECK (`backend` in ('nova','zun','kubernetes'))
) ENGINE=InnoDB;

CREATE TABLE `chat_runtime_resources` (
  `id` char(36) NOT NULL,
  `pool_id` char(36) NOT NULL,
  `generation` int NOT NULL DEFAULT 1,
  `role` varchar(10) NOT NULL,
  `backend` varchar(10) NOT NULL,
  `logical_project_id` varchar(64) DEFAULT NULL,
  `logical_user_id` varchar(64) DEFAULT NULL,
  `run_id` char(36) DEFAULT NULL,
  `desired_state` varchar(20) NOT NULL DEFAULT 'requested',
  `observed_state` varchar(20) NOT NULL DEFAULT 'requested',
  `request_fingerprint` char(64) NOT NULL,
  `cloud_profile_id` varchar(190) DEFAULT NULL,
  `cloud_project_id` varchar(64) DEFAULT NULL,
  `provider_id` varchar(190) DEFAULT NULL,
  `address` varchar(190) DEFAULT NULL,
  `port` int DEFAULT NULL,
  `image_ref` varchar(255) NOT NULL,
  `policy_digest` char(64) NOT NULL,
  `bootstrap_token_hash` char(64) DEFAULT NULL,
  `bootstrap_expires_at` datetime(6) DEFAULT NULL,
  `certificate_fingerprint` char(64) DEFAULT NULL,
  `heartbeat_at` datetime(6) DEFAULT NULL,
  `ready_at` datetime(6) DEFAULT NULL,
  `deadline_at` datetime(6) DEFAULT NULL,
  `active_slots` int NOT NULL DEFAULT 0,
  `ingress_member_id` varchar(190) DEFAULT NULL,
  `failure_code` varchar(100) DEFAULT NULL,
  `created_at` datetime(6) NOT NULL DEFAULT current_timestamp(6),
  `updated_at` datetime(6) NOT NULL DEFAULT current_timestamp(6) ON UPDATE current_timestamp(6),
  `deleted_at` datetime(6) DEFAULT NULL,
  `guest_profile_id` varchar(190) DEFAULT NULL,
  `guest_profile_digest` char(64) DEFAULT NULL,
  `idle_since` datetime(6) DEFAULT NULL,
  `accepting` tinyint NOT NULL DEFAULT 1,
  `drain_requested_at` datetime(6) DEFAULT NULL,
  `drain_ack_at` datetime(6) DEFAULT NULL,
  `drain_reason` varchar(100) DEFAULT NULL,
  `api_counter_snapshot` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`api_counter_snapshot`)),
  `api_counter_snapshot_at` datetime(6) DEFAULT NULL,
  `certificate_not_after` datetime DEFAULT NULL,
  `pending_certificate_fingerprint` char(64) DEFAULT NULL,
  `pending_certificate_pem` mediumtext DEFAULT NULL,
  `pending_certificate_not_after` datetime DEFAULT NULL,
  `pending_certificate_expires_at` datetime DEFAULT NULL,
  `previous_certificate_fingerprint` char(64) DEFAULT NULL,
  `previous_certificate_valid_until` datetime DEFAULT NULL,
  `renewal_request_id` char(36) DEFAULT NULL,
  `renewal_csr_hash` char(64) DEFAULT NULL,
  `cluster_profile_id` varchar(64) DEFAULT NULL,
  `namespace` varchar(63) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_runtime_resource_provider` (`cloud_profile_id`,`cloud_project_id`,`provider_id`),
  UNIQUE KEY `uq_runtime_resource_run_generation` (`run_id`,`generation`),
  UNIQUE KEY `uq_runtime_resource_cluster_provider` (`cluster_profile_id`,`namespace`,`provider_id`),
  KEY `idx_runtime_resource_pool_state` (`pool_id`,`observed_state`),
  KEY `idx_runtime_resource_desired` (`desired_state`,`deadline_at`),
  CONSTRAINT `fk_runtime_resource_pool` FOREIGN KEY (`pool_id`) REFERENCES `chat_runtime_pools` (`id`),
  CONSTRAINT `fk_runtime_resource_run` FOREIGN KEY (`run_id`) REFERENCES `chat_runs` (`id`)
) ENGINE=InnoDB;

CREATE TABLE `chat_scheduler_leases` (
  `scheduler_name` varchar(100) NOT NULL,
  `owner` varchar(190) NOT NULL,
  `expires_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`scheduler_name`)
) ENGINE=InnoDB;

CREATE TABLE `chat_skills` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `scope` varchar(10) NOT NULL,
  `owner_user_id` varchar(64) DEFAULT NULL,
  `owner_project_id` varchar(64) DEFAULT NULL,
  `project_id` varchar(64) DEFAULT NULL,
  `name` varchar(100) NOT NULL,
  `description` varchar(500) DEFAULT NULL,
  `instructions` text NOT NULL,
  `slug` varchar(100) DEFAULT NULL,
  `argument_hint` varchar(500) DEFAULT NULL,
  `user_invocable` tinyint NOT NULL,
  `model_invocable` tinyint NOT NULL,
  `content_hash` char(64) DEFAULT NULL,
  `source_package_id` char(36) DEFAULT NULL,
  `source_package_version` varchar(64) DEFAULT NULL,
  `managed_by_package` tinyint NOT NULL,
  `is_active` tinyint NOT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_chat_skills_project_slug` (`project_id`,`slug`),
  KEY `idx_chat_skill_owner` (`owner_user_id`),
  KEY `idx_chat_skill_scope` (`scope`)
) ENGINE=InnoDB;

CREATE TABLE `chat_temp_threads` (
  `id` char(36) NOT NULL,
  `project_id` varchar(64) NOT NULL,
  `user_id` varchar(64) NOT NULL,
  `history` mediumtext NOT NULL,
  `active_run_id` char(36) DEFAULT NULL,
  `expires_at` datetime NOT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_chat_temp_threads_owner_expiry` (`project_id`,`user_id`,`expires_at`)
) ENGINE=InnoDB;

CREATE TABLE `chat_tool_approvals` (
  `run_id` char(36) NOT NULL,
  `call_id` varchar(190) NOT NULL,
  `tool_name` mediumtext NOT NULL,
  `arguments` mediumtext NOT NULL,
  `arguments_ciphertext` mediumtext DEFAULT NULL,
  `dispatch_hmac` char(64) DEFAULT NULL,
  `preview_fingerprint` char(64) DEFAULT NULL,
  `decision_hmac` char(64) DEFAULT NULL,
  `source` varchar(30) DEFAULT NULL,
  `effect` varchar(30) DEFAULT NULL,
  `tool_definition_hash` char(64) DEFAULT NULL,
  `config_fingerprint` char(64) DEFAULT NULL,
  `destination_origin` varchar(255) DEFAULT NULL,
  `expected_state_revision` bigint DEFAULT NULL,
  `writer_fence` bigint DEFAULT NULL,
  `status` varchar(20) NOT NULL,
  `requested_at` datetime(6) NOT NULL,
  `decided_at` datetime(6) DEFAULT NULL,
  `decided_by_user_id` varchar(64) DEFAULT NULL,
  `expires_at` datetime(6) NOT NULL,
  PRIMARY KEY (`run_id`,`call_id`),
  KEY `idx_chat_tool_approvals_pending_expiry` (`status`,`expires_at`),
  CONSTRAINT `chat_tool_approvals_ibfk_1` FOREIGN KEY (`run_id`) REFERENCES `chat_runs` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE `chat_usage_logs` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `project_id` varchar(64) NOT NULL,
  `user_id` varchar(64) NOT NULL,
  `conversation_id` char(36) DEFAULT NULL,
  `model_name` varchar(190) NOT NULL,
  `provider` varchar(100) DEFAULT NULL,
  `prompt_tokens` int NOT NULL,
  `completion_tokens` int NOT NULL,
  `cache_read_input_tokens` int NOT NULL DEFAULT 0,
  `cache_creation_5m_input_tokens` int NOT NULL DEFAULT 0,
  `cache_creation_1h_input_tokens` int NOT NULL DEFAULT 0,
  `raw_cost` decimal(20,10) NOT NULL,
  `credited_cost` decimal(18,8) NOT NULL,
  `source` varchar(10) NOT NULL,
  `api_key_id` bigint DEFAULT NULL,
  `event_id` varchar(64) DEFAULT NULL,
  `pricing_status` varchar(20) NOT NULL,
  `pricing_snapshot` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`pricing_snapshot`)),
  `run_id` char(36) DEFAULT NULL,
  `usage_components` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`usage_components`)),
  `provider_reported_cost` decimal(20,10) DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `provider_id` bigint DEFAULT NULL,
  `provider_account_id` bigint DEFAULT NULL,
  `provider_credential_id` bigint DEFAULT NULL,
  `provider_credential_generation` bigint DEFAULT NULL,
  `provider_backend` varchar(40) DEFAULT NULL,
  `provider_backend_version` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `event_id` (`event_id`),
  KEY `idx_chat_usage_api_key_id` (`api_key_id`,`id`),
  KEY `idx_chat_usage_api_key_created` (`api_key_id`,`created_at`),
  KEY `idx_chat_usage_run_id` (`run_id`),
  KEY `idx_chat_usage_provider_account` (`provider_account_id`,`created_at`),
  KEY `idx_chat_usage_project_created` (`project_id`,`created_at`),
  KEY `idx_chat_usage_user_created` (`user_id`,`created_at`)
) ENGINE=InnoDB;

CREATE TABLE `chat_worker_registrations` (
  `id` char(36) NOT NULL,
  `worker_identity` varchar(190) NOT NULL,
  `boot_id` char(36) NOT NULL,
  `resource_id` char(36) DEFAULT NULL,
  `pool_id` char(36) DEFAULT NULL,
  `protocol_versions` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`protocol_versions`)),
  `plugin_digest` char(64) NOT NULL,
  `schema_version` int NOT NULL,
  `capacity` int NOT NULL,
  `active_count` int NOT NULL DEFAULT 0,
  `accepting` tinyint NOT NULL DEFAULT 1,
  `draining` tinyint NOT NULL DEFAULT 0,
  `drain_started_at` datetime(6) DEFAULT NULL,
  `heartbeat_at` datetime(6) NOT NULL DEFAULT current_timestamp(6),
  `created_at` datetime(6) NOT NULL DEFAULT current_timestamp(6),
  `resource_generation` int DEFAULT NULL,
  `certificate_fingerprint` char(64) DEFAULT NULL,
  `workload_classes` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '["online_text", "online_media"]' CHECK (json_valid(`workload_classes`)),
  `drain_ack_at` datetime(6) DEFAULT NULL,
  `auxiliary_active` int NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_worker_registration_boot` (`worker_identity`,`boot_id`),
  KEY `idx_worker_registration_heartbeat` (`accepting`,`heartbeat_at`),
  KEY `fk_worker_registration_resource` (`resource_id`),
  KEY `fk_worker_registration_pool` (`pool_id`),
  CONSTRAINT `fk_worker_registration_pool` FOREIGN KEY (`pool_id`) REFERENCES `chat_runtime_pools` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_worker_registration_resource` FOREIGN KEY (`resource_id`) REFERENCES `chat_runtime_resources` (`id`) ON DELETE SET NULL,
  CONSTRAINT `ck_worker_registration_auxiliary_active` CHECK (`auxiliary_active` >= 0),
  CONSTRAINT `ck_worker_registration_workload_classes` CHECK (json_type(`workload_classes`) = 'ARRAY' and json_length(`workload_classes`) > 0 and json_depth(`workload_classes`) = 2 and json_contains('["online_text","online_media","batch"]',`workload_classes`) = 1)
) ENGINE=InnoDB;

CREATE TABLE `chat_workspaces` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `owner_user_id` varchar(64) NOT NULL,
  `name` varchar(100) NOT NULL,
  `description` varchar(500) DEFAULT NULL,
  `instructions` mediumtext DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_chat_workspaces_owner` (`owner_user_id`)
) ENGINE=InnoDB;

CREATE TABLE `llm_models` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `provider_id` bigint NOT NULL,
  `model_name` varchar(190) NOT NULL,
  `display_name` varchar(150) DEFAULT NULL,
  `is_active` tinyint NOT NULL,
  `is_title_model` tinyint NOT NULL,
  `is_memory_model` tinyint NOT NULL,
  `input_price` decimal(20,10) DEFAULT NULL,
  `output_price` decimal(20,10) DEFAULT NULL,
  `cache_read_price` decimal(20,10) DEFAULT NULL,
  `cache_write_price` decimal(20,10) DEFAULT NULL,
  `cache_write_1h_price` decimal(20,10) DEFAULT NULL,
  `models_dev_model_id` varchar(190) DEFAULT NULL,
  `price_source` varchar(20) DEFAULT NULL,
  `price_metadata` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`price_metadata`)),
  `capabilities` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`capabilities`)),
  `capability_source` varchar(20) DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `model_kind` varchar(16) NOT NULL DEFAULT 'text',
  `media_pricing` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`media_pricing`)),
  `sort_order` int NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_llm_models_provider_model` (`provider_id`,`model_name`),
  KEY `idx_llm_models_active` (`is_active`),
  CONSTRAINT `llm_models_ibfk_1` FOREIGN KEY (`provider_id`) REFERENCES `llm_providers` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chk_llm_models_sort_order` CHECK (`sort_order` >= 0)
) ENGINE=InnoDB;

CREATE TABLE `llm_provider_accounts` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `provider_id` bigint NOT NULL,
  `name` varchar(100) NOT NULL,
  `is_active` tinyint NOT NULL DEFAULT 1,
  `priority` int NOT NULL DEFAULT 0,
  `weight` int NOT NULL DEFAULT 1,
  `allowed_model_ids` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`allowed_model_ids`)),
  `allowed_capabilities` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`allowed_capabilities`)),
  `quota_group` varchar(100) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_provider_account_name` (`provider_id`,`name`),
  CONSTRAINT `fk_provider_account_endpoint` FOREIGN KEY (`provider_id`) REFERENCES `llm_providers` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chk_provider_account_weight` CHECK (`weight` > 0 and `priority` >= 0)
) ENGINE=InnoDB;

CREATE TABLE `llm_provider_auth_attempts` (
  `provider_id` bigint NOT NULL,
  `id` char(36) NOT NULL,
  `initiated_by_user_id` varchar(64) NOT NULL,
  `initiated_by_project_id` varchar(64) NOT NULL,
  `provider_generation` bigint NOT NULL,
  `encrypted_payload` text DEFAULT NULL,
  `status` varchar(16) NOT NULL,
  `expires_at` datetime NOT NULL,
  `next_poll_at` datetime NOT NULL,
  `created_at` datetime NOT NULL,
  `credential_id` bigint NOT NULL,
  PRIMARY KEY (`credential_id`),
  UNIQUE KEY `uq_llm_provider_auth_attempts_id` (`id`),
  KEY `idx_auth_attempt_provider` (`provider_id`),
  CONSTRAINT `fk_auth_attempt_credential` FOREIGN KEY (`credential_id`) REFERENCES `llm_provider_credentials` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_llm_provider_auth_attempts_provider` FOREIGN KEY (`provider_id`) REFERENCES `llm_providers` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE `llm_provider_credentials` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `account_id` bigint NOT NULL,
  `name` varchar(100) NOT NULL,
  `auth_mode` varchar(32) NOT NULL,
  `encrypted_api_key` text DEFAULT NULL,
  `api_key_env` varchar(128) DEFAULT NULL,
  `encrypted_subscription_tokens` text DEFAULT NULL,
  `subscription_status` varchar(24) NOT NULL DEFAULT 'disconnected',
  `subscription_expires_at` datetime DEFAULT NULL,
  `expires_at` datetime DEFAULT NULL,
  `cooldown_until` datetime DEFAULT NULL,
  `generation` bigint NOT NULL DEFAULT 0,
  `is_active` tinyint NOT NULL DEFAULT 1,
  `priority` int NOT NULL DEFAULT 0,
  `weight` int NOT NULL DEFAULT 1,
  `allowed_model_ids` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`allowed_model_ids`)),
  `allowed_capabilities` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`allowed_capabilities`)),
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_provider_credential_name` (`account_id`,`name`),
  CONSTRAINT `fk_provider_credential_account` FOREIGN KEY (`account_id`) REFERENCES `llm_provider_accounts` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chk_provider_credential_weight` CHECK (`weight` > 0 and `priority` >= 0)
) ENGINE=InnoDB;

CREATE TABLE `llm_providers` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL,
  `provider_type` varchar(40) NOT NULL,
  `api_base` varchar(255) DEFAULT NULL,
  `encrypted_api_key` text DEFAULT NULL,
  `encrypted_billing_admin_key` text DEFAULT NULL,
  `is_active` tinyint NOT NULL,
  `margin_multiplier` decimal(8,4) NOT NULL,
  `models_dev_provider_id` varchar(100) DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `api_key_env` varchar(128) DEFAULT NULL,
  `auth_mode` varchar(32) NOT NULL DEFAULT 'api_key',
  `encrypted_subscription_tokens` text DEFAULT NULL,
  `subscription_status` varchar(24) NOT NULL DEFAULT 'disconnected',
  `subscription_expires_at` datetime DEFAULT NULL,
  `subscription_generation` bigint NOT NULL DEFAULT 0,
  `api_provider` varchar(40) NOT NULL,
  `sort_order` int NOT NULL DEFAULT 0,
  `selection_policy` varchar(16) NOT NULL DEFAULT 'priority',
  `selected_credential_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_llm_providers_name` (`name`),
  CONSTRAINT `chk_llm_providers_sort_order` CHECK (`sort_order` >= 0)
) ENGINE=InnoDB;

CREATE TABLE `user_wallets` (
  `user_id` varchar(64) NOT NULL,
  `project_id` varchar(64) DEFAULT NULL,
  `balance_credits` decimal(18,8) NOT NULL,
  `max_quota_monthly` decimal(18,8) DEFAULT NULL,
  `used_quota_this_month` decimal(18,8) NOT NULL,
  `reserved_credits` decimal(18,8) NOT NULL,
  `quota_period_start` date DEFAULT NULL,
  `is_active` tinyint NOT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `max_quota_weekly` decimal(18,8) DEFAULT NULL,
  PRIMARY KEY (`user_id`)
) ENGINE=InnoDB;
